window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-acf9a06df490537f"]={"versions": [{"id": "FIG-acf9a06df490537f", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung von Zeitsynchronisations-Schnittstellen (Time Synch Interfaces) im Kontext der AUTOSAR-Manifest-Spezifikation (Adaptive Platform). Es definiert die Vererbungshierarchie von Port-Interfaces für Zeitsynchronisation ausgehend von den Basistypen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basis-Metaklasse, erbt von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>TimeSynchronizationInterface</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>PortInterface</code>.\n</li><li><code>TimeSynchronizationPureLocalInterface</code>: Konkrete Spezialisierung von <code>TimeSynchronizationInterface</code> ohne Attribute.\n</li><li><code>TimeSynchronizationMasterInterface</code>: Spezialisierung von <code>TimeSynchronizationInterface</code> mit dem Attribut <code>+ timeBaseKind :TimeSynchronizationKindEnum</code>.\n</li><li><code>TimeSynchronizationSlaveInterface</code>: Spezialisierung von <code>TimeSynchronizationInterface</code> mit dem Attribut <code>+ timeBaseKind :TimeSynchronizationKindEnum</code>.\n</li><li><code>«enumeration» TimeSynchronizationKindEnum</code>: Aufzählungstyp mit den Literalen <code>offset</code> und <code>synchronized</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zeigt die Spezialisierungshierarchie der Port-Interfaces für Master-, Slave- und rein lokale Zeitsynchronisation sowie die Typisierung des Attributs <code>timeBaseKind</code> über das Enumeration-Literal.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die metamodellkonforme Deklaration von Port-Interfaces für Zeitbasen in Software-Komponenten und Manifesten. Master- und Slave-Schnittstellen erfordern die Angabe von <code>timeBaseKind</code> (<code>offset</code> oder <code>synchronized</code>), während reine lokale Zeitbasen (<code>TimeSynchronizationPureLocalInterface</code>) keine Synchronisationsart über dieses Attribut deklarieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fd8be845d5da16d9", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung von Zeitsynchronisations-Schnittstellen (Time Synch Interfaces) im Kontext der AUTOSAR-Manifest-Spezifikation (Adaptive Platform). Es definiert die Vererbungshierarchie von Port-Interfaces für Zeitsynchronisation ausgehend von den Basistypen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basis-Metaklasse, erbt von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>TimeSynchronizationInterface</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>PortInterface</code>.\n</li><li><code>TimeSynchronizationPureLocalInterface</code>: Konkrete Spezialisierung von <code>TimeSynchronizationInterface</code> ohne Attribute.\n</li><li><code>TimeSynchronizationMasterInterface</code>: Spezialisierung von <code>TimeSynchronizationInterface</code> mit dem Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum</code>.\n</li><li><code>TimeSynchronizationSlaveInterface</code>: Spezialisierung von <code>TimeSynchronizationInterface</code> mit dem Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum</code>.\n</li><li><code>«enumeration» TimeSynchronizationKindEnum</code>: Aufzählungstyp mit den Literalen <code>offset</code> und <code>synchronized</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zeigt die Spezialisierungshierarchie der Port-Interfaces für Master-, Slave- und rein lokale Zeitsynchronisation sowie die Typisierung des Attributs <code>timeBaseKind</code> über das Enumeration-Literal.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die metamodellkonforme Deklaration von Port-Interfaces für Zeitbasen in Software-Komponenten und Manifesten. Master- und Slave-Schnittstellen erfordern die Angabe von <code>timeBaseKind</code> (<code>offset</code> oder <code>synchronized</code>), während reine lokale Zeitbasen (<code>TimeSynchronizationPureLocalInterface</code>) keine Synchronisationsart über dieses Attribut deklarieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fe3fcfa68e9c3d95", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung von Zeitsynchronisations-Schnittstellen (Time Synch Interfaces) im Kontext der AUTOSAR-Manifest-Spezifikation (Adaptive Platform). Es definiert die Vererbungshierarchie von Port-Interfaces für Zeitsynchronisation ausgehend von den Basistypen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basis-Metaklasse, erbt von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>TimeSynchronizationInterface</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>PortInterface</code>.\n</li><li><code>TimeSynchronizationPureLocalInterface</code>: Konkrete Spezialisierung von <code>TimeSynchronizationInterface</code> ohne Attribute.\n</li><li><code>TimeSynchronizationMasterInterface</code>: Spezialisierung von <code>TimeSynchronizationInterface</code> mit dem Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum</code>.\n</li><li><code>TimeSynchronizationSlaveInterface</code>: Spezialisierung von <code>TimeSynchronizationInterface</code> mit dem Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum</code>.\n</li><li><code>«enumeration» TimeSynchronizationKindEnum</code>: Aufzählungstyp mit den Literalen <code>offset</code> und <code>synchronized</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zeigt die Spezialisierungshierarchie der Port-Interfaces für Master-, Slave- und rein lokale Zeitsynchronisation sowie die Typisierung des Attributs <code>timeBaseKind</code> über das Enumeration-Literal.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die metamodellkonforme Deklaration von Port-Interfaces für Zeitbasen in Software-Komponenten und Manifesten. Master- und Slave-Schnittstellen erfordern die Angabe von <code>timeBaseKind</code> (<code>offset</code> oder <code>synchronized</code>), während reine lokale Zeitbasen (<code>TimeSynchronizationPureLocalInterface</code>) keine Synchronisationsart über dieses Attribut deklarieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-391872d85bdfde8a", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung von Zeitsynchronisations-Schnittstellen (Time Synch Interfaces) im Kontext der AUTOSAR-Manifest-Spezifikation (Adaptive Platform). Es definiert die Vererbungshierarchie von Port-Interfaces für Zeitsynchronisation ausgehend von den Basistypen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basis-Metaklasse, erbt von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>TimeSynchronizationInterface</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>PortInterface</code>.\n</li><li><code>TimeSynchronizationPureLocalInterface</code>: Konkrete Spezialisierung von <code>TimeSynchronizationInterface</code> ohne Attribute.\n</li><li><code>TimeSynchronizationMasterInterface</code>: Spezialisierung von <code>TimeSynchronizationInterface</code> mit dem Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum</code>.\n</li><li><code>TimeSynchronizationSlaveInterface</code>: Spezialisierung von <code>TimeSynchronizationInterface</code> mit dem Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum</code>.\n</li><li><code>«enumeration» TimeSynchronizationKindEnum</code>: Aufzählungstyp mit den Literalen <code>offset</code> und <code>synchronized</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zeigt die Spezialisierungshierarchie der Port-Interfaces für Master-, Slave- und rein lokale Zeitsynchronisation sowie die Typisierung des Attributs <code>timeBaseKind</code> über das Enumeration-Literal.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die metamodellkonforme Deklaration von Port-Interfaces für Zeitbasen in Software-Komponenten und Manifesten. Master- und Slave-Schnittstellen erfordern die Angabe von <code>timeBaseKind</code> (<code>offset</code> oder <code>synchronized</code>), während reine lokale Zeitbasen (<code>TimeSynchronizationPureLocalInterface</code>) keine Synchronisationsart über dieses Attribut deklarieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-15fecd97041b7ac0", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung synchronisierter Zeitbasen-Schnittstellen im Kontext der AUTOSAR-Manifest-Spezifikation (Adaptive Platform). Es definiert die Vererbungshierarchie von Provider- und Consumer-Port-Interfaces ausgehend von den Basistypen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basis-Metaklasse, erbt von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>AbstractSynchronizedTimeBaseInterface</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>PortInterface</code>.\n</li><li><code>SynchronizedTimeBaseProviderInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> mit dem Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum</code>.\n</li><li><code>SynchronizedTimeBaseConsumerInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> ohne eigene Attribute.\n</li><li><code>«enumeration» TimeSynchronizationKindEnum</code>: Aufzählungstyp mit den Literalen <code>offset</code> und <code>synchronized</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zeigt die Spezialisierungsbeziehungen von Provider- und Consumer-Schnittstellen für synchronisierte Zeitbasen sowie die Zuordnung der Synchronisationsart (<code>timeBaseKind</code>) zur Provider-Schnittstelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gibt die metamodellkonforme Struktur für synchrone Zeitbasen vor. Ein Provider (<code>SynchronizedTimeBaseProviderInterface</code>) deklariert die Art der Zeitbasis über <code>timeBaseKind</code> (<code>offset</code> oder <code>synchronized</code>). Consumer (<code>SynchronizedTimeBaseConsumerInterface</code>) nutzen die Schnittstelle ohne eigenes <code>timeBaseKind</code>-Attribut.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4454a9c5c691bda8", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung synchronisierter Zeitbasen-Schnittstellen im Kontext der AUTOSAR-Manifest-Spezifikation (Adaptive Platform). Es definiert die Vererbungshierarchie von Provider- und Consumer-Port-Interfaces ausgehend von den Basistypen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basis-Metaklasse, erbt von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>AbstractSynchronizedTimeBaseInterface</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>PortInterface</code>.\n</li><li><code>SynchronizedTimeBaseProviderInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> mit dem Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum</code>.\n</li><li><code>SynchronizedTimeBaseConsumerInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> ohne eigene Attribute.\n</li><li><code>«enumeration» TimeSynchronizationKindEnum</code>: Aufzählungstyp mit den Literalen <code>offset</code> und <code>synchronized</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zeigt die Spezialisierungsbeziehungen von Provider- und Consumer-Schnittstellen für synchronisierte Zeitbasen sowie die Zuordnung der Synchronisationsart (<code>timeBaseKind</code>) zur Provider-Schnittstelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gibt die metamodellkonforme Struktur für synchrone Zeitbasen vor. Ein Provider (<code>SynchronizedTimeBaseProviderInterface</code>) deklariert die Art der Zeitbasis über <code>timeBaseKind</code> (<code>offset</code> oder <code>synchronized</code>). Consumer (<code>SynchronizedTimeBaseConsumerInterface</code>) nutzen die Schnittstelle ohne eigenes <code>timeBaseKind</code>-Attribut.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d21ae1c61e98164e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung synchronisierter Zeitbasen-Schnittstellen im Kontext der AUTOSAR-Manifest-Spezifikation (Adaptive Platform). Es definiert die Vererbungshierarchie von Provider- und Consumer-Port-Interfaces ausgehend von den Basistypen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basis-Metaklasse, erbt von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>AbstractSynchronizedTimeBaseInterface</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>PortInterface</code>.\n</li><li><code>SynchronizedTimeBaseProviderInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> mit dem Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum [0..1]</code>.\n</li><li><code>SynchronizedTimeBaseConsumerInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> ohne eigene Attribute.\n</li><li><code>«enumeration» TimeSynchronizationKindEnum</code>: Aufzählungstyp mit den Literalen <code>offset</code> und <code>synchronized</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zeigt die Spezialisierungsbeziehungen von Provider- und Consumer-Schnittstellen für synchronisierte Zeitbasen sowie die Zuordnung der Synchronisationsart (<code>timeBaseKind</code>) zur Provider-Schnittstelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gibt die metamodellkonforme Struktur für synchrone Zeitbasen vor. Das Attribut <code>timeBaseKind</code> im <code>SynchronizedTimeBaseProviderInterface</code> ist optional mit der Multiplizität <code>[0..1]</code> definiert. Consumer (<code>SynchronizedTimeBaseConsumerInterface</code>) deklarieren kein eigenes <code>timeBaseKind</code>-Attribut.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-231ea9e1642bc8e3", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung synchronisierter Zeitbasen-Schnittstellen im Kontext der AUTOSAR-Manifest-Spezifikation (Adaptive Platform). Es definiert die Vererbungshierarchie von Provider- und Consumer-Port-Interfaces ausgehend von den Basistypen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basis-Metaklasse, erbt von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>AbstractSynchronizedTimeBaseInterface</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>PortInterface</code>.\n</li><li><code>SynchronizedTimeBaseProviderInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> mit dem Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum [0..1]</code>.\n</li><li><code>SynchronizedTimeBaseConsumerInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> ohne eigene Attribute.\n</li><li><code>«enumeration» TimeSynchronizationKindEnum</code>: Aufzählungstyp mit den Literalen <code>offset</code> und <code>synchronized</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zeigt die Spezialisierungsbeziehungen von Provider- und Consumer-Schnittstellen für synchronisierte Zeitbasen sowie die Zuordnung der Synchronisationsart (<code>timeBaseKind</code>) zur Provider-Schnittstelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gibt die metamodellkonforme Struktur für synchrone Zeitbasen vor. Das Attribut <code>timeBaseKind</code> im <code>SynchronizedTimeBaseProviderInterface</code> ist optional mit der Multiplizität <code>[0..1]</code> definiert. Consumer (<code>SynchronizedTimeBaseConsumerInterface</code>) deklarieren kein eigenes <code>timeBaseKind</code>-Attribut.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cc021416f4eda613", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung synchronisierter Zeitbasen-Schnittstellen im Kontext der AUTOSAR-Manifest-Spezifikation (Adaptive Platform). Es definiert die Vererbungshierarchie von Provider- und Consumer-Port-Interfaces ausgehend von den Basistypen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basis-Metaklasse, erbt von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>AbstractSynchronizedTimeBaseInterface</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>PortInterface</code>.\n</li><li><code>SynchronizedTimeBaseProviderInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> ohne eigene Attribute.\n</li><li><code>SynchronizedTimeBaseConsumerInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> ohne eigene Attribute.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zeigt die Spezialisierungsbeziehungen von Provider- und Consumer-Schnittstellen für synchronisierte Zeitbasen ausgehend von <code>AbstractSynchronizedTimeBaseInterface</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gibt die metamodellkonforme Vererbungshierarchie für synchrone Zeitbasen-Schnittstellen vor. Sowohl Provider (<code>SynchronizedTimeBaseProviderInterface</code>) als auch Consumer (<code>SynchronizedTimeBaseConsumerInterface</code>) spezialisieren <code>AbstractSynchronizedTimeBaseInterface</code> als leere Schnittstellenklassen ohne eigene Metamodell-Attribute.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e9a971a246cfebed", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung synchronisierter Zeitbasen-Schnittstellen im Kontext der AUTOSAR-Manifest-Spezifikation (Adaptive Platform). Es definiert die Vererbungshierarchie von Provider- und Consumer-Port-Interfaces ausgehend von den Basistypen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basis-Metaklasse, erbt von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>AbstractSynchronizedTimeBaseInterface</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>PortInterface</code>.\n</li><li><code>SynchronizedTimeBaseProviderInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> ohne eigene Attribute.\n</li><li><code>SynchronizedTimeBaseConsumerInterface</code>: Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> ohne eigene Attribute.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zeigt die Spezialisierungsbeziehungen von Provider- und Consumer-Schnittstellen für synchronisierte Zeitbasen ausgehend von <code>AbstractSynchronizedTimeBaseInterface</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gibt die metamodellkonforme Vererbungshierarchie für synchrone Zeitbasen-Schnittstellen vor. Sowohl Provider (<code>SynchronizedTimeBaseProviderInterface</code>) als auch Consumer (<code>SynchronizedTimeBaseConsumerInterface</code>) spezialisieren <code>AbstractSynchronizedTimeBaseInterface</code> als leere Schnittstellenklassen ohne eigene Metamodell-Attribute.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-acf9a06df490537f", "to": "FIG-fd8be845d5da16d9", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Attribut <code>timeBaseKind</code> in <code>TimeSynchronizationMasterInterface</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code>+ timeBaseKind: TimeSynchronizationKindEnum</code>).\n</li><li>Attribut <code>timeBaseKind</code> in <code>TimeSynchronizationSlaveInterface</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code>+ timeBaseKind: TimeSynchronizationKindEnum</code>).\n</li></ul>"}, {"from": "FIG-fd8be845d5da16d9", "to": "FIG-fe3fcfa68e9c3d95", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fe3fcfa68e9c3d95", "to": "FIG-391872d85bdfde8a", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-391872d85bdfde8a", "to": "FIG-15fecd97041b7ac0", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>TimeSynchronizationInterface</code> umbenannt / ersetzt durch <code>AbstractSynchronizedTimeBaseInterface</code>.\n</li><li><code>TimeSynchronizationMasterInterface</code> ersetzt durch <code>SynchronizedTimeBaseProviderInterface</code> mit Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum</code>.\n</li><li><code>TimeSynchronizationSlaveInterface</code> und <code>TimeSynchronizationPureLocalInterface</code> entfernt.\n</li><li><code>SynchronizedTimeBaseConsumerInterface</code> als neue Spezialisierung von <code>AbstractSynchronizedTimeBaseInterface</code> hinzugefügt (ohne Attribute).\n</li><li>Positionierung der Enumeration <code>TimeSynchronizationKindEnum</code> im Diagramm von rechts nach links verschoben.\n</li></ul>"}, {"from": "FIG-15fecd97041b7ac0", "to": "FIG-4454a9c5c691bda8", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4454a9c5c691bda8", "to": "FIG-d21ae1c61e98164e", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut <code>timeBaseKind</code> in <code>SynchronizedTimeBaseProviderInterface</code>: Multiplizität explizit auf <code>[0..1]</code> spezifiziert (<code>+ timeBaseKind: TimeSynchronizationKindEnum [0..1]</code>).\n</li></ul>"}, {"from": "FIG-d21ae1c61e98164e", "to": "FIG-231ea9e1642bc8e3", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-231ea9e1642bc8e3", "to": "FIG-cc021416f4eda613", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SynchronizedTimeBaseProviderInterface</code>: Attribut <code>+ timeBaseKind: TimeSynchronizationKindEnum [0..1]</code> entfernt.\n</li><li><code>«enumeration» TimeSynchronizationKindEnum</code>: Enumeration mit Literalen <code>offset</code> und <code>synchronized</code> entfernt.\n</li></ul>"}, {"from": "FIG-cc021416f4eda613", "to": "FIG-e9a971a246cfebed", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
